firstLabel:
		issueOrPullRequest(number: ${number}
			... on PullRequest {
				comments {
					totalCount
				}
				commits(last: 1) {
					nodes {
						commit {
							oid
						}
					}
				}
				author {
					avatarUrl
					login
					url
				}
				body
				labels(first: 10) {
					nodes {
						name
					}
				}
				merged
				number
				publishedAt
				state
				title
				url
			}
			... on Issue {
				comments {
					totalCount
				}
				author {
					avatarUrl
					login
					url
				}
				body
				labels(first: 10) {
					nodes {
						name
					}
				}
				number
				publishedAt
				state
				title
				url
			}
		}
	}
}

